SELECT
FROM inventory i LEFT JOIN product p ON i.product_id = p.id LEFT JOIN warehouse w ON i.warehouse_id = w.id WHERE 1=1
AND p.name LIKE CONCAT('%', #{keyword}, '%')
AND i.product_id = #{productId}
AND i.warehouse_id = #{warehouseId}
AND i.status = #{status}
AND i.quantity = 0
AND i.quantity > 0 AND p.min_stock IS NOT NULL AND p.min_stock > 0 AND i.quantity <= p.min_stock
AND (i.quantity > 0 AND (p.min_stock IS NULL OR p.min_stock = 0 OR i.quantity > p.min_stock))
ORDER BY i.update_time DESC LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM inventory i LEFT JOIN product p ON i.product_id = p.id WHERE 1=1
AND p.name LIKE CONCAT('%', #{keyword}, '%')
AND i.product_id = #{productId}
AND i.warehouse_id = #{warehouseId}
AND i.status = #{status}
AND i.quantity = 0
AND i.quantity > 0 AND p.min_stock IS NOT NULL AND p.min_stock > 0 AND i.quantity <= p.min_stock
AND (i.quantity > 0 AND (p.min_stock IS NULL OR p.min_stock = 0 OR i.quantity > p.min_stock))

